/* 2. Base Typography
------------------------------------------------------------------------------*/


a {
  text-decoration: none;
}

/* main container */
#wrapper-menu-aast {
  width: 100%;
  display: flex;
  min-height: 100%;
  position: relative;
  flex-wrap: wrap;
  background-color: #fff;
  justify-content: space-between;
  align-content: space-between;
  -webkit-transform: translateX(0);
  transform: translateX(0);
  transition: -webkit-transform 800ms cubic-bezier(0.68, -0.55, 0.265, 1.55);
  transition: transform 800ms cubic-bezier(0.68, -0.55, 0.265, 1.55);
  transition: transform 800ms cubic-bezier(0.68, -0.55, 0.265, 1.55),
    -webkit-transform 800ms cubic-bezier(0.68, -0.55, 0.265, 1.55);
}
.main-container-aasta {
  width: 100%;
}
/* header */
.main-header {
  width: 100%;
  height: auto;
}
h3 {
 /* font-size: 30px;*/
}
/* responsive nav for small devices */

/* hamburger-aasta menu */
.hamburger-aasta {
  padding: 0;
  margin: 0;
  height: 25px;
  width: 25px;
  text-align: center;
  background-color: transparent;
}
.hamburger-aasta:not(.close) {
  position: absolute;
  top: 10px;
  right: 20px;
  z-index: 7;
  border: 0;
  display: none;
  width: auto;
  height: auto;
  border: 1px solid #a4a3a3;
  border-radius: 2px;
  padding: 10px;
  direction: rtl;
}
.hamburger-aasta:hover,
.hamburger-aasta:focus {
  background-color: transparent;
  outline: none;
}
.hamburger-aasta .line {
  width: 50px;
  height: 4px;
  background-color: #3c3c3b;
  display: block;
  margin: 10px 0;
  transition: all 0.4s ease-in;
  right: 0;
  position: revert;
}
.hamburger-aasta:hover {
  cursor: pointer;
}
.hamburger-aasta.close {
  padding: 10px;
}
.hamburger-aasta.close .wrap {
  position: relative;
  width: 30px;
  height: 30px;
  display: block;
}
.hamburger-aasta.close .line {
  margin: 0;
  width: 100%;
  position: absolute;
  top: calc(50% - 2px);
  transform: rotate(45deg);
  background-color: #000;
}
.hamburger-aasta.close .line:last-child {
  transform: rotate(-45deg);
}
.hamburger-aasta.is-active .line:nth-child(1) {
  transform: rotate(45deg);
  position: absolute;
  left: 0;
  top: 5px;
}
.hamburger-aasta.is-active .line:nth-child(2) {
  opacity: 0;
  visibility: hidden;
  position: absolute;
  transition: none;
}
.hamburger-aasta.is-active .line:nth-child(3) {
  transform: rotate(-45deg);
  position: absolute;
  left: 0;
  top: 5px;
}
#menu-aast {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: 100%;
  height: 100%;
  background-color: #f1f1f1;
  max-width: 99%;
  transition: all 0.3s ease-in-out;
  z-index: 999;
  -webkit-transform: translateX(-150%);
  transform: translateX(-150%);
  transition: -webkit-transform 500ms cubic-bezier(0.68, -0.55, 0.265, 1.55);
  transition: transform 500ms cubic-bezier(0.68, -0.55, 0.265, 1.55);
  transition: transform 500ms cubic-bezier(0.68, -0.55, 0.265, 1.55),
    -webkit-transform 500ms cubic-bezier(0.68, -0.55, 0.265, 1.55);
  transition-delay: 0.2s;
  overflow-x: hidden;
  overflow-y: auto;
}

#mobilenav-aast .nav-logo {
  padding: 15px;
}
#mobilenav-aast ul,
#mobilenav-aast li {
  padding: 0;
  margin: 0;
  list-style: none;
  transition: 0;
  position: relative;
}
#mobilenav-aast .caret {
  display: block;
  width: 36px;
  position: absolute;
  top: 1px;
  right: 20px;
  cursor: pointer;
  background-color: #132b61;
}
#mobilenav-aast .caret:not(.trigger-caret) {
  pointer-events: none;
}
#mobilenav-aast .caret:after {
  content: "";
  border: 2px solid #fff;
  border-bottom: 0;
  border-left: 0;
  transform: rotate(45deg);
  display: block;
  position: absolute;
  height: 15px;
  width: 15px;
  top: 15px;
  left: 8px;
}
#mobilenav-aast ul a {
  display: block;
  padding: 10px 15px;
  cursor: pointer;
  z-index: 2;
  font-size: 16px;
  text-decoration: none;
  color: #fff;
  background: #132b61;
  border-bottom: 1px solid #fff;
  transition: none;
}
#mobilenav-aast ul a:hover {
  background: #132b61;
}
#mobilenav-aast .has-sub > a {
  padding-right: 40px;
}
#mobilenav-aast li li a {
  font-size: 14px;
  text-decoration: none;
  color: #dddddd;
  background: #132b61;
}
#mobilenav-aast .nav-backdrop {
  position: fixed;
  height: 100%;
  width: 100%;
  background: rgba(0, 0, 0, 0.8);
  z-index: -1;
  opacity: 0;
  visibility: hidden;
  transition: all 0.5s ease-in;
}
#mobilenav-aast .menu-outer {
  padding-bottom: 60px;
  overflow: hidden;
  overflow-y: auto;
  /* box-shadow: rgba(0, 0, 0, 0.24) 0px 3px 8px; */
  max-height: 100%;
}
/* #wrapper.nav_is_visible {
  -webkit-transform: translateX(300px);
  transform: translateX(300px);
} */

/* slide menu */
#mobilenav-aast .slide-menu {
  background-color: #f1f1f1;
  position: fixed;
  top: 0;
  right: -100%;
  width: 100%;
  min-height: 100%;
  height: 100%;
  background-color: #f1f1f1;
  transition: all 0.5s ease;
  z-index: 0;
  -webkit-transform: translateX(150%);
  transform: translateX(150%);
  overflow: hidden;
}
#mobilenav-aast .slide-menu.sub-open {
  -webkit-transform: translateX(0);
  transform: translateX(0);
  opacity: 1;
  z-index: 9;
  visibility: visible;
  right: 0;
}
#mobilenav-aast .slide-menu .submenu-header {
  padding: 10px 15px;
  min-height: 45px;
  background-color: #ededed;
  color: #3c3c3b;
  padding-left: 50px;
  border-bottom: 1px solid #fff;
  position: relative;
  cursor: pointer;
  text-align: center;
}
#mobilenav-aast .slide-menu .submenu-header:before {
  content: "";
  border: 2px solid #3c3c3b;
  border-bottom: 0;
  border-left: 0;
  transform: rotate(-135deg);
  display: block;
  position: absolute;
  height: 15px;
  width: 15px;
  top: 15px;
  left: 20px;
}

/*--------- home page ------------*/
/* banner part */

/*-------HEADER-------*/
/* nav */
.main-container-aasta .navigation{
  width: 100%;
  height: auto;
  position: relative;
  background-color: #ffffff;
}
.main-container-aasta .navigation ul {
  padding: 0;
  margin: 0;
  list-style: none;
  gap: 3px;
  z-index: 9999999;
}
.main-container-aasta .navigationul li {
  padding: 0;
  margin: 0;
  list-style: none;
}
.nav-aast > ul {
  display: flex;
  margin: 0;
  justify-content: left;
}
.nav-aast > ul > li {
  position: relative;
  margin: 0;
  list-style: none;
  transition: background-color 0s ease;
  padding: 5px;
  border-radius: 3px;
}
.nav-aast ul li:last-child {
  margin-right: 0;
}
.nav-aast > ul > li > a {
  font-size: 16px;
  color: #393939;
  text-transform: capitalize;
  font-weight: 650;
  padding: 10px 15px 10px 0;
  display: block;
  transition: background-color 0.5s ease;
}
.nav-aast > ul > li.active,
.nav-aast > ul > li:hover {
  color: #322348;
  /* transition: background-color 0s ease; */
  /* background-color: #003480; */
}
.nav-aast > ul > li:hover > a {
  color: #ff5722;
  text-decoration: none;
  /* color: #fff; */
}
.nav-aast > ul > li > a:hover,
.nav-aast > ul > li.active > a {
  color: #f44336 !important;
  text-decoration: none;
}

/* drop-down */
.nav-aast ul li ul {
  position: absolute;
  top: calc(100%);
  left: 0;
  margin: 0;
  width: 320px;
  z-index: 4;
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
  transition: 0.3s;
  box-shadow: rgba(0, 0, 0, 0.24) 0px 3px 8px;
  min-width: 300px;
}
.nav-aast ul li ul li {
  position: relative;
  display: flex;
  padding: 0;
  margin-bottom: 0;
}
.nav-aast ul li ul li:last-child > a {
  border-bottom: none;
}
.nav-aast ul li ul ul {
  position: absolute;
  left: 0px;
  top: 100%;
  left: 100%;
  top: 0;
}
.nav-aast ul li ul li a {
  padding: 8px 15px 9px 10px;
  width: 100%;
  display: block;
  font-size: 16px;
  background-color: #f9f9f9;
  color: #2b2b2b;
  border: none;
  border-bottom: 1px solid #fff;
  text-transform: capitalize;
  font-weight: 600;
  transition: background-color 0.5s ease;
  overflow: hidden;
  transition: all .3s ease;
}
.nav-aast ul li:hover > ul {
  margin-top: 0;
  visibility: visible;
  opacity: 1;
  pointer-events: auto;
  -moz-animation: fadeInDown 0.3s ease-in;
  -webkit-animation: fadeInDown 0.3s ease-in;
  animation: fadeInDown 0.3s ease-in;
  /* z-index: 99999; */
}
.nav-aast ul li ul li:hover > ul {
  top: 25px;
  box-shadow: rgba(0, 0, 0, 0.24) 0px 3px 8px;
}
.nav-aast ul li ul li:hover > a {
  background-color: #f8f8f8;
  color: #1e1d1d;
  text-decoration: none;
  transition: all .3s ease;
}
@keyframes fadeInDown {
  0% {
    opacity: 0;
    -webkit-transform: translateY(-20px);
    -ms-transform: translateY(-20px);
    transform: translateY(-20px);
  }
  100% {
    opacity: 1;
    -webkit-transform: translateY(0);
    -ms-transform: translateY(0);
    transform: translateY(0);
  }
}

