    zoom: 1;
}


/*.carousel li { margin-right: 5px; }*/


/* Direction Nav */

.flex-direction-nav {
    *height: 0;
}

.flex-direction-nav a {
    text-decoration: none;
    display: block;
    width: 60px;
    height: 60px;
    margin: -30px 0 0;
    position: absolute;
    top: 50%;
    z-index: 10;
    overflow: hidden;
    opacity: 0;
    cursor: pointer;
    border: 1px solid rgba(214, 214, 214, 0.5);
    border-radius: 50%;
    font-size: 0;
    color: transparent;
    text-align: center;
}

.flex-direction-nav a:hover {
    background-color: rgba(214, 214, 214, 0.5);
}

.flex-direction-nav a:hover:before {
    color: #ffffff;
}

.flex-direction-nav .flex-prev {
    left: 30px;
}

.flex-direction-nav .flex-next {
    right: 30px;
}

.flexslider:hover .flex-prev {
    opacity: 1;
}

.flexslider:hover .flex-next {
    opacity: 1;
}

.flexslider:hover .flex-next:hover,
.flexslider:hover .flex-prev:hover {
    opacity: 1;
}

.flex-direction-nav .flex-disabled {
    opacity: 0;
    filter: alpha(opacity=0);
    cursor: default;
}

.flex-direction-nav a:before {
    font-size: 20px;
    font-family: "flexslider-icon";
    color: #d6d6d6;
    position: absolute;
    top: 13px;
    left: 18px;
    display: inline-block;
    content: '\f001';
}

.flex-direction-nav a.flex-next:before {
    font-family: "flexslider-icon";
    left: 19px;
}


/* Pause/Play */

.flex-pauseplay a {
    display: block;
    width: 20px;
    height: 20px;
    position: absolute;
    bottom: 5px;
    left: 10px;
    opacity: 0.8;
    z-index: 10;
    overflow: hidden;
    cursor: pointer;
    color: #000;
}

.flex-pauseplay a:before {
    font-size: 20px;
    display: inline-block;
    content: "\e6a2";
}

.flex-pauseplay a:hover {
    opacity: 1;
}

.flex-pauseplay a.flex-play:before {
    content: "\e711";
}


/* Control Nav */

.flex-control-nav {
    width: 100%;
    position: absolute;
    bottom: 42px;
    text-align: center;
    z-index: 10;
}

.flex-control-nav li {
    text-align: center;
    display: inline-block;
    padding: 0 4px;
    zoom: 1;
    *display: inline;
}

.flex-control-paging li a {
    width: 12px;
    height: 12px;
    display: block;
    color: transparent;
    border: 2px solid #343434;
    cursor: pointer;
    text-indent: -9999px;
    border-radius: 50%;
}

.ds .flex-control-paging li a,
.cs .flex-control-paging li a {
    border-color: #ffffff;
}

.flex-control-paging li a:hover {
    border-color: #1d3052;
}

.flex-control-paging li a.flex-active {
    border-color: #1d3052;
}

.flex-control-thumbs {
    margin: 5px 0 0;
    position: static;
    overflow: hidden;
}

.flex-control-thumbs li {
    width: 25%;
    float: left;
    margin: 0;
}

.flex-control-thumbs img {
    width: 100%;
    display: block;
    opacity: .7;
    cursor: pointer;
}

.flex-control-thumbs img:hover {
    opacity: 1;
}

.flex-control-thumbs .flex-active {
    opacity: 1;
    cursor: default;
}

@media screen and (max-width: 600px) {
    .flex-direction-nav .flex-prev {
        top: 14%;
    }

    .flex-direction-nav .flex-next {
        top: 14%;
    }
}


/* custom nav for flex slider*/

.flex-custom-nav {
    text-align: center;
    position: absolute;
    bottom: 38px;
    right: 0;
    left: 0;
    z-index: 3;
    line-height: 1;
    -webkit-transition: all 0.2s ease-in-out 0s;
    transition: all 0.2s ease-in-out 0s;
}

.flex-custom-nav .flex-control-nav {
    width: auto;
    display: inline-block;
    position: static;
}

.flex-custom-nav .flex-custom-link {
    font-size: 12px;
    position: relative;
    bottom: 7px;
    margin: 0 8px;
    color: #343434;
}

